package com.example.xrealprobe;
import android.app.*; import android.os.*; import android.content.*; import android.hardware.display.*; import android.hardware.usb.*; import android.graphics.*; import android.view.*; import android.widget.*; import java.util.*;
public class MainActivity extends Activity {
 TextView report; DisplayManager dm; Presentation presentation; LinearLayout layout;
 @Override public void onCreate(Bundle b){super.onCreate(b); dm=(DisplayManager)getSystemService(DISPLAY_SERVICE); layout=new LinearLayout(this);layout.setOrientation(1); ScrollView scroll=new ScrollView(this);scroll.addView(layout);setContentView(scroll);button("Refresh USB / displays",()->scan());button("Copy diagnostic report",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("XREAL",report.getText()));});button("Stereo test on external display",()->showStereo());button("Stereo test on phone (preview)",()->{setContentView(new Stereo(this));});report=new TextView(this);report.setTextIsSelectable(true);layout.addView(report);scan();}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->r.run());layout.addView(b);}
 void scan(){StringBuilder s=new StringBuilder("USB devices (descriptors only):\n");UsbManager u=(UsbManager)getSystemService(USB_SERVICE);for(UsbDevice d:u.getDeviceList().values()){s.append(String.format(Locale.US,"VID=%04x PID=%04x interfaces=%d\n",d.getVendorId(),d.getProductId(),d.getInterfaceCount()));for(int i=0;i<d.getInterfaceCount();i++){UsbInterface f=d.getInterface(i);s.append("  interface "+f.getId()+" class="+f.getInterfaceClass()+" subclass="+f.getInterfaceSubclass()+" endpoints="+f.getEndpointCount()+"\n");}}s.append("\nDisplays:\n");for(Display d:dm.getDisplays()){Display.Mode m=d.getMode();s.append(d.getDisplayId()+" "+d.getName()+" "+m.getPhysicalWidth()+"x"+m.getPhysicalHeight()+" @"+m.getRefreshRate()+"\n");}report.setText(s);}
 void showStereo(){Display[] ds=dm.getDisplays(DisplayManager.DISPLAY_CATEGORY_PRESENTATION);if(ds.length==0){Toast.makeText(this,"No external presentation display; try desktop mode",Toast.LENGTH_LONG).show();return;}if(presentation!=null)presentation.dismiss();presentation=new Presentation(this,ds[0]);presentation.setContentView(new Stereo(presentation.getContext()));presentation.show();}
 @Override protected void onDestroy(){if(presentation!=null)presentation.dismiss();super.onDestroy();}
 static class Stereo extends View {Paint p=new Paint(3);long t=SystemClock.uptimeMillis();Stereo(Context c){super(c);}void line(Canvas c,float x,float y,float a,float b,int color,float w){p.setColor(color);p.setStrokeWidth(w);c.drawLine(x,y,a,b,p);} @Override protected void onDraw(Canvas c){c.drawColor(Color.BLACK);float w=getWidth()/2f,h=getHeight();double ang=(SystemClock.uptimeMillis()-t)*.0007;for(int eye=0;eye<2;eye++){c.save();c.clipRect(eye*w,0,(eye+1)*w,h);float cx=(eye+.5f)*w,cy=h*.5f;float scale=Math.min(w,h)*.43f;float[][] pts=new float[8][2];for(int i=0;i<8;i++){double x=((i&1)==0?-1:1)*.48,y=((i&2)==0?-1:1)*.48,z=((i&4)==0?-1:1)*.48;double rx=x*Math.cos(ang)+z*Math.sin(ang),rz=-x*Math.sin(ang)+z*Math.cos(ang)+3;double e=eye==0?-.032:.032;pts[i][0]=cx+(float)(scale*((rx-e)/rz+e/3.0));pts[i][1]=cy+(float)(scale*y/rz);}for(int i=0;i<8;i++)for(int j=0;j<3;j++){int k=i^(1<<j);if(k>i)line(c,pts[i][0],pts[i][1],pts[k][0],pts[k][1],Color.CYAN,4);}p.setColor(Color.WHITE);p.setTextSize(h*.035f);c.drawText(eye==0?"LEFT":"RIGHT",eye*w+20,h*.12f,p);line(c,cx-15,cy,cx+15,cy,Color.GRAY,2);line(c,cx,cy-15,cx,cy+15,Color.GRAY,2);c.restore();}postInvalidateDelayed(16);}}
}